3	/// Word caption pages re-paged from their own words on the current canvas (spec §11 VR-40):
4	/// what File ▸ Re-lay Captions for This Canvas and `relay_captions` do (VR-45), and step (6) of
5	/// Make Vertical (`VerticalVersion+Plan.swift`). W-7 and W-10 stand: `CaptionPages.repage` is
6	/// the measuring pager with lead 0 and `CaptionLayout.place` the one writer, so a re-laid page
7	/// is built exactly as a generated one is — from the words the pages hold, so every correction
8	/// is kept (the owner's answer, 2026-11-01).
9	///
10	/// `place(replacing:)` removes each replaced track with its clips first, so a track is
11	/// replaced only when every page on it is recognised: a track holding a page with no timings,
12	/// or in a style Frame Job does not make, is KEPT and named with its reason. Names no `rc_*`.
13	enum CaptionRelayout {
14	    /// The undo step's name (VR-45).
15	    static let actionName = "Re-lay Captions"
16	
17	    /// A caption track whose pages are all in one recognised style.
18	    struct Track: Equatable {
19	        let track: UInt32
20	        let name: String
21	        let style: CaptionStyle
22	        let looks: CaptionLooks
23	    }
24	
25	    /// A caption track left as placed, and why.
26	    struct Kept: Equatable {
27	        let track: UInt32
28	        let name: String
29	        let reason: String
30	    }
31	
32	    /// A track re-laid: the new track's id, the old one's, its name, style and page count.
33	    struct Relaid: Equatable {
34	        let track: UInt32
35	        let replaced: UInt32
36	        let name: String
37	        let style: CaptionStyle
38	        let pages: Int
39	    }
40	
41	    /// What the survey found, each list in stack order, back first.
42	    struct Survey: Equatable {
43	        let recognised: [Track]
44	        let kept: [Kept]
45	    }
46	
47	    struct Outcome: Equatable {
48	        var relaid: [Relaid]
49	        var kept: [Kept]
50	    }
51	
52	    /// VR-40 (a): the caption tracks of one container — named as `CaptionLayout` names them,
53	    /// holding at least one clip and only text clips — each recognised or kept with the first
54	    /// reason that applies.
55	    static func survey(_ snapshot: ProjectSnapshot) -> Survey {
56	        var recognised: [Track] = []
57	        var kept: [Kept] = []
58	        for track in snapshot.tracks where CaptionLayout.isCaptionTrackName(track.name) {
59	            let clips = snapshot.clips(onTrack: track.id)
60	            guard !clips.isEmpty, clips.allSatisfy(isText) else { continue }
61	            func keep(_ reason: String) {
62	                kept.append(Kept(track: track.id, name: track.name, reason: reason))
63	            }
64	            if track.matte != .none {
65	                keep("it is a matte track")
66	                continue
67	            }
68	            let timed = clips.map { Self.words(of: $0) }
69	            if timed.contains(where: { $0 == nil }) {
70	                keep("it holds a page with no word timings")
71	                continue
72	            }
73	            if timed.contains(where: { $0?.isEmpty ?? true }) {
74	                keep("it holds a page none of whose words starts inside it")
75	                continue
76	            }
77	            let styles = clips.map { clip in clip.text.flatMap(recognise) }
78	            if styles.contains(where: { $0 == nil }) {
79	                keep("it holds a page in a style Frame Job does not make")
80	                continue
81	            }
82	            guard let first = styles[0],
83	                styles.allSatisfy({ $0?.style == first.style && $0?.looks == first.looks })
84	            else {
85	                keep("its pages are in more than one style")
86	                continue
87	            }
88	            recognised.append(
89	                Track(track: track.id, name: track.name, style: first.style, looks: first.looks))
90	        }
91	        return Survey(recognised: recognised, kept: kept)
92	    }
93	
94	    private static func isText(_ clip: ClipSnapshot) -> Bool {
95	        if case .text = clip.source { return true }
96	        return false
97	    }
98	
99	    /// VR-40 (b): the word style and looks a page was made in — its font the style's and its
100	    /// `word_style` the style's with those looks — or nil. Subtitles is never a match.
101	    static func recognise(_ text: TextProps) -> (style: CaptionStyle, looks: CaptionLooks)? {
102	        for style in CaptionStyle.allCases where style.isWordStyle && text.font == style.font {
103	            for bits in 0 ..< 8 {
104	                let looks = CaptionLooks(
105	                    slide: bits & 1 != 0, fill: bits & 2 != 0, dim: bits & 4 != 0)
106	                guard looks == looks.live(for: style) else { continue }
107	                if text.wordStyle == style.wordStyle(looks) { return (style, looks) }
108	            }
109	        }
110	        return nil
111	    }
112	
113	    /// VR-40 (c): a page's timed words in TIMELINE ticks, one per whitespace token of
114	    /// `content`, speaker nil — only those whose start lies inside the clip (a split's or a
115	    /// trim's half holds the words of the part it lost). Nil for a clip with no text, no
116	    /// words or a count that differs from the tokens; empty when none starts inside.
117	    static func words(of clip: ClipSnapshot) -> [CaptionCues.Word]? {
118	        guard let text = clip.text, !text.words.isEmpty else { return nil }
119	        let tokens = text.content.split(whereSeparator: \.isWhitespace)
120	        guard tokens.count == text.words.count else { return nil }
121	        let inside = clip.start ..< clip.start + clip.duration
122	        return zip(tokens, text.words).compactMap { token, word in
123	            let start = clip.start + word.start
124	            guard inside.contains(start) else { return nil }
125	            return CaptionCues.Word(
126	                text: String(token), start: start, end: clip.start + word.end, speaker: nil)
127	        }
128	    }
129	
130	    /// VR-40 (e): each track re-paged on the trial's canvas, back to front, as one batch per
131	    /// track tried op by op on a scratch copy; a `LayoutError` or a refusal keeps the track
132	    /// and applies nothing of it. Then the new track back at the old one's index, hidden and
133	    /// locked as it was. Throws only the core's invalid input.
134	    static func relay(_ tracks: [Track], on trial: inout SwitchAngle.Trial) throws -> Outcome {
135	        var outcome = Outcome(relaid: [], kept: [])
136	        for track in tracks {
137	            let before = trial.project.snapshot
138	            guard let index = before.tracks.firstIndex(where: { $0.id == track.track }) else {
139	                continue
140	            }
141	            let old = before.tracks[index]
142	            let canvas = CGSize(width: before.canvas.width, height: before.canvas.height)
143	            let frame = max(before.canvas.fps.frameDuration, 1)
144	            let request = CaptionPages.Request(style: track.style, canvas: canvas)
145	            var cues: [CaptionLayout.Cue] = []
146	            for clip in before.clips(onTrack: track.track).sorted(by: { $0.start < $1.start }) {
147	                cues += CaptionPages.repage(
148	                    words(of: clip) ?? [], span: clip.start ..< clip.start + clip.duration,
149	                    frame: frame, request: request, clip: clip.id)
150	            }
151	            func keep(_ reason: String) {
152	                outcome.kept.append(Kept(track: track.track, name: track.name, reason: reason))
153	            }
154	            let plan: CaptionLayout.Plan
155	            do {
156	                plan = try CaptionLayout.place(
157	                    cues, in: trial.project, trackBase: track.name, style: track.style,
158	                    looks: track.looks, replacing: [track.track])
159	            } catch let error as CaptionLayout.LayoutError {
160	                keep(error.errorDescription ?? "the captions could not be placed")
161	                continue
162	            }
163	            var scratch = trial
164	            var refused: String?
165	            for op in plan.ops {
166	                if let why = try scratch.require(op) {
167	                    refused = why
168	                    break
169	                }
170	            }
171	            if let refused {
172	                keep(refused)
173	                continue
174	            }
175	            let known = Set(before.tracks.map(\.id))
176	            guard
177	                let made = scratch.project.snapshot.tracks.first(where: {
178	                    !known.contains($0.id)
179	                })
180	            else {
181	                keep("no caption track was made")
182	                continue
183	            }
184	            var follow: [ReelOp] = [.moveTrack(track: made.id, index: index)]
185	            if old.hidden { follow.append(.setTrack(track: made.id, hidden: true)) }
186	            if old.locked { follow.append(.setTrack(track: made.id, locked: true)) }
187	            for op in follow {
188	                if let why = try scratch.require(op) {
189	                    refused = why
190	                    break
191	                }
192	            }
193	            if let refused {
194	                keep(refused)
195	                continue
196	            }
197	            trial = scratch
198	            outcome.relaid.append(
199	                Relaid(
200	                    track: made.id, replaced: track.track, name: made.name, style: track.style,
201	                    pages: plan.clips))
202	        }
203	        return outcome
204	    }
205	
206	    /// VR-45: the survey and the re-lay of one container's handle (the editor's
207	    /// `editedProject`); the outcome's kept tracks are the survey's, then the re-lay's.
208	    static func plan(_ project: ReelProject) throws -> (ops: [ReelOp], outcome: Outcome) {
209	        let found = survey(project.snapshot)
210	        var trial = SwitchAngle.Trial(project: project)
211	        var outcome = try relay(found.recognised, on: &trial)
212	        outcome.kept = found.kept + outcome.kept
213	        return (trial.ops, outcome)
214	    }
215	
216	    /// The answer's `relaid` and `kept`, as both tools spell them.
217	    static func answerFields(_ outcome: Outcome) -> [String: Any] {
218	        [
219	            "relaid": outcome.relaid.map { relaid -> [String: Any] in
220	                [
221	                    "track": Int(relaid.track), "replaced": Int(relaid.replaced),
222	                    "name": relaid.name, "style": relaid.style.rawValue, "pages": relaid.pages,
223	                ]
224	            },
225	            "kept": outcome.kept.map { kept -> [String: Any] in
226	                ["track": Int(kept.track), "name": kept.name, "reason": kept.reason]
227	            },
228	        ]
229	    }
230	
231	    /// One kept track's line, as the notice and Make Vertical's summary say it.
232	    static func keptLine(_ kept: Kept) -> String {
233	        let why = kept.reason.hasSuffix(".") ? String(kept.reason.dropLast()) : kept.reason
234	        return "Caption track \"\(kept.name)\" is kept as placed: \(why)."
235	    }
236	
237	    /// The menu's informational sheet: nil when nothing was kept.
238	    static func noticeText(_ outcome: Outcome) -> String? {
239	        guard !outcome.kept.isEmpty else { return nil }
240	        let count = outcome.relaid.count
241	        let head = count == 0
242	            ? "No caption track was re-laid."
243	            : "Re-laid \(count) caption track\(count == 1 ? "" : "s") for this canvas."
244	        return ([head] + outcome.kept.map(keptLine)).joined(separator: "\n")
245	    }
246	}
